def solve(text):
    if not text:
        return []
    rows = []
    row = []
    field = ''
    quoted = False
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if quoted:
            if c == '"':
                if i + 1 < n and text[i + 1] == '"':
                    field += '"'
                    i += 1
                else:
                    quoted = False
            else:
                field += c
        elif c == '"':
            quoted = True
        elif c == ',':
            row.append(field)
            field = ''
        elif c == '\n' or c == '\r':
            row.append(field)
            rows.append(row)
            row = []
            field = ''
            if c == '\r' and i + 1 < n and text[i + 1] == '\n':
                i += 1
        else:
            field += c
        i += 1
    if text[n - 1] != '\n' and text[n - 1] != '\r':
        row.append(field)
        rows.append(row)
    return rows

